import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CiKk3sJz.js";const x=JSON.parse('{"title":"漫画 · 第 43 话 text-wrap · field-sizing · interpolate-size：排版细节三件套","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.43-text-wrap-field-sizing.md","filePath":"comics/css/EP.43-text-wrap-field-sizing.md","lastUpdated":1792579602000}'),r={name:"comics/css/EP.43-text-wrap-field-sizing.md"};function l(n,e,s,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画-·-第-43-话-text-wrap-·-field-sizing-·-interpolate-size-排版细节三件套" tabindex="-1">漫画 · 第 43 话 text-wrap · field-sizing · interpolate-size：排版细节三件套 <a class="header-anchor" href="#漫画-·-第-43-话-text-wrap-·-field-sizing-·-interpolate-size-排版细节三件套" aria-label="Permalink to &quot;漫画 · 第 43 话 text-wrap · field-sizing · interpolate-size：排版细节三件套&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/27-text-wrap-field-sizing">docs/css/27-text-wrap-field-sizing.md</a> ｜ 原画：<a href="./EP.43-text-wrap-field-sizing.svg">EP.43-text-wrap-field-sizing.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。居中标题折成 14:2 两行像被狗啃、textarea 固定 4 行内容一多就出滚动条、<code>height: auto</code> 动画直接跳变——三个「小而美」的排版细节逼疯了她，只能靠 max-height hack 和 JS 监听 input 硬补。</li><li><strong>标签君</strong>：HTML5 结构师，搬出三个原生属性：<code>text-wrap</code> 管换行策略、<code>field-sizing</code> 让输入框随内容伸缩、<code>interpolate-size</code> 解开 auto 不可动画的世纪封印。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>UI 的质感往往死在细节上：标题换行字数不均、输入框要么挤要么空、折叠面板高度动画跳变。过去这三件事都要写 JS 或 hack 来补，代码丑还脆弱。本话像素酱学会三件原生武器——<code>text-wrap: balance</code> 让标题两行字数尽量相等、<code>field-sizing: content</code> 让 textarea 随内容自动长高、<code>interpolate-size: allow-keywords</code> 让 <code>height: 0 → auto</code> 平滑过渡，全部零 JS。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>三个小而美的痛：标题两行 14:2 字数严重不均；textarea 固定行数，内容多了出滚动条、少了留大片空白；<code>height: auto</code> 无法过渡，只能用 max-height hack 截断或写 50 行 JS 解决 1 行的事。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>text-wrap: balance</code> 均分标题（限 10 行以内）、<code>text-wrap: pretty</code> 防孤词（无行数限制）；<code>field-sizing: content</code> 让 textarea/input/select 随内容伸缩，配 min/max-height 兜底；<code>interpolate-size: allow-keywords</code> 写在 <code>:root</code> 上，auto、min-content、max-content 等关键字尺寸全部可动画。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：标题均分（视觉平衡专业）、输入框自适应（内容多自动长高、封顶 max-height）、auto 平滑过渡（折叠面板零 JS）、渐进增强（不支持时自动回退默认行为，无副作用）。Chrome 114+ / Safari 17.5+ / Firefox 121+ 已全绿。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>balance 均分标题限 10 行；pretty 防孤词无行数限制，长段落用 pretty。</li><li>field-sizing: content 只认 textarea/input/select；min/max-height 必须兜底。</li><li>interpolate-size: allow-keywords 是全局开关，写在 :root 上全站生效。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>text-wrap: balance</code> 要限制 10 行以内，而 <code>pretty</code> 没有行数限制？</p><p><strong>答</strong>：balance 需要浏览器对每一行尝试多种断行组合并评分，计算量随行数指数级增长，10 行是规范定的性能上限；pretty 只做「最后一行不留孤词」的局部调整，代价与行数线性相关，所以不限行数。实务上：标题/引用用 balance，正文段落用 pretty。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>text-wrap 三策略对比 + field-sizing 自适应输入框 + interpolate-size 折叠面板：<a href="./../../examples/css/27-text-wrap-field-sizing/index-01-text-wrap-field-sizing.html">examples/css/27-text-wrap-field-sizing/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 44 话《Web Components 入门》——React 组件 Vue 用不了、Vue 组件 React 用不了？浏览器原生组件化三件套：template 惰性模板、slot 插槽分发、customElements.define 自定义元素，零依赖跨框架复用。</p>',22)])])}const f=a(r,[["render",l]]);export{x as __pageData,f as default};
